# S-01: turns data-cache/drugs_app.json (Ministry of Health registry, from fetch_drugs.py) into the app file drugs_il.js.
# Row: [hebrew name, english name, form (en), form (he), [[ingredient code, ingredient, dose], ...], [barcodes]]
import json, datetime
D = json.load(open('data-cache/drugs_app.json', encoding='utf-8'))
rows = [[d['h'], d['e'], d['fe'], d['f'], d['a'], d['b']] for d in D if d['a']]
out = ('/* S-01: Israeli Ministry of Health drug registry (registries.health.gov.il), human medicines that are not cancelled. '
       'Generated by tools/make_drugs_js.py on %s. Used to tell whether a medicine is a full substitute for another. */\n'
       'window.IL_DRUGS=' % datetime.date.today().isoformat()) + json.dumps(rows, ensure_ascii=False, separators=(',', ':')) + ';\n'
open('app/src/main/assets/drugs_il.js', 'w', encoding='utf-8').write(out)
print(len(rows), 'rows,', len(out.encode()), 'bytes')
